  :root{
    --bg: #ffffff;
    --bg-alt: #fafaf9;
    --surface: #f4f4f2;
    --line: rgba(23,20,15,0.14);
    --text: #171410;
    --muted: #6f6a5c;
    --accent: #ff6044;
    --accent-soft: rgba(255,96,68,0.08);
    --radius: 999px;
    --lg-issb: url("data:image/svg+xml;base64,");
    --lg-mdplunv: url("data:image/svg+xml;base64,");
    --lg-mdpl: url("data:image/svg+xml;base64,");
    --lg-biruni: url("data:image/png;base64,");
    --lg-thy: url("data:image/png;base64,");
    --lg-ttech: url("data:image/png;base64,");
    --lg-tci: url("data:image/png;base64,");
    --lg-slz: url("data:image/png;base64,");
    --lg-suunto: url("data:image/svg+xml;base64,");
    --lg-adx: url("data:image/png;base64,");
    --lg-sporterest: url("data:image/png;base64,");
    --lg-dpi: url("data:image/png;base64,");
    --lg-leo: url("data:image/png;base64,");
    --pp: url("data:image/jpeg;base64,");
  }
  *{box-sizing:border-box; margin:0; padding:0;}
  html{scroll-behavior:smooth;}
  body{
    background:var(--bg);
    color:var(--text);
    font-family:'Space Grotesk',sans-serif;
    font-size:16px;
    line-height:1.65;
    letter-spacing:-0.005em;
    overflow-x:hidden;
  }
  h1,h2,h3,h4{font-family:'Space Grotesk',sans-serif; font-weight:500; letter-spacing:-0.025em;}
  em{font-style:normal; color:var(--accent); font-weight:500;}
  a{color:inherit; text-decoration:none;}
  .wrap{max-width:1720px; margin:0 auto; padding:0 40px;}
  .eyebrow{
    font-family:'JetBrains Mono',monospace;
    font-size:12px; letter-spacing:0.12em; text-transform:uppercase;
    color:var(--accent); display:flex; align-items:center; gap:10px;
  }
  .eyebrow::before{content:""; width:20px; height:1px; background:var(--accent);}

  /* NAV — grid-icon MENÜ / logo / local time / avatar+CTA pill, like Hanza hero */
  header{
    position:fixed; top:0; left:0; right:0; z-index:60;
    color:#f3ede2;
    background:transparent; border-bottom:1px solid transparent;
    transition:color .3s, background-color .3s, border-color .3s, backdrop-filter .3s;
  }
  header.scrolled{
    color:#f3ede2;
    background:rgba(15,13,10,0.94);
    backdrop-filter:blur(14px) saturate(1.2);
    -webkit-backdrop-filter:blur(14px) saturate(1.2);
    border-bottom-color:rgba(255,255,255,0.12);
  }
  header.scrolled .nav-cta{ background:rgba(255,255,255,0.10); padding:4px 6px 4px 4px; }
  header.scrolled nav{ padding:10px 40px; }
  header.scrolled .nav-avatar{ width:28px; height:28px; }
  header.scrolled .nav-arrow{ width:30px; height:30px; font-size:13px; }
  @media (max-width: 900px){ header.scrolled nav{ padding:10px 20px; } }
  nav{
    display:flex; align-items:center; justify-content:space-between;
    padding:26px 40px; max-width:1720px; margin:0 auto;
    transition:padding .3s;
  }
  .nav-left{display:flex; align-items:center; gap:16px;}
  .menu-toggle{
    display:flex; align-items:center; gap:10px; cursor:pointer;
    background:none; border:1px solid transparent; border-radius:5px; padding:6px 10px; margin-left:-10px;
    font-family:'JetBrains Mono',monospace; font-size:12.5px; letter-spacing:0.08em; color:inherit;
    transition:border-color .25s, color .25s;
  }
  .menu-toggle:focus-visible{outline:2px solid var(--accent); outline-offset:2px;}
  .menu-toggle.open{border-color:var(--accent); color:var(--accent);}
  .menu-toggle .grid-icon{display:grid; grid-template-columns:1fr 1fr; gap:3px; width:13px;}
  .menu-toggle .grid-icon span{width:5px; height:5px; border-radius:1px; background:currentColor; display:block; transition:transform .3s, opacity .3s;}
  .menu-toggle.open .grid-icon span:nth-child(1){transform:translate(2px,2px);}
  .menu-toggle.open .grid-icon span:nth-child(4){transform:translate(-2px,-2px);}
  .menu-toggle.open .grid-icon span:nth-child(2), .menu-toggle.open .grid-icon span:nth-child(3){opacity:0.3;}
  .nav-sep{width:26px; height:1px; background:currentColor; opacity:0.35;}
  .logo{font-family:'Space Grotesk',sans-serif; font-size:16px; letter-spacing:0.02em; font-weight:700; color:inherit;}
  .logo sup{font-size:9px; margin-left:1px;}
  .nav-mid{display:flex; align-items:center; gap:26px;}
  .nav-mid a{
    font-family:'Space Grotesk',sans-serif; font-weight:500; font-size:12.5px;
    letter-spacing:0.11em; text-transform:uppercase; color:inherit; opacity:0.82;
    padding:6px 0; transition:opacity .25s, color .25s;
  }
  .nav-mid a:hover{color:var(--accent); opacity:1;}
  .nav-mid a:focus-visible{outline:2px solid var(--accent); outline-offset:3px;}
  @media (max-width: 1180px){
    .nav-mid{display:none;}
  }
  .nav-right{display:flex; align-items:center; gap:0;}
  .lang{display:flex; align-items:center; gap:7px; margin-right:20px;
    font-family:'JetBrains Mono',monospace; font-size:11.5px; letter-spacing:0.1em; color:inherit;}
  .lang span{opacity:0.35;}
  .lang button{
    background:none; border:none; padding:4px 2px; cursor:pointer; color:inherit;
    font:inherit; letter-spacing:inherit; opacity:0.5; transition:opacity .25s, color .25s;
  }
  .lang button:hover{opacity:0.85;}
  .lang button.on{opacity:1; color:var(--accent);}
  .lang button:focus-visible{outline:2px solid var(--accent); outline-offset:2px;}
  @media (max-width: 1180px){ .lang{margin-right:12px;} }
  .nav-cta{
    display:flex; align-items:center; gap:14px;
    background:rgba(15,13,10,0.88); border-radius:999px;
    padding:6px 8px 6px 6px;
    transition:background-color .3s, padding .3s;
  }
  .nav-avatar{
    width:34px; height:34px; border-radius:50%; overflow:hidden; flex-shrink:0; transition:width .3s, height .3s;
    background:var(--pp) center 22% / cover no-repeat, #2a221b;
  }
  .nav-cta-text{
    font-family:'JetBrains Mono',monospace; font-size:11.5px; letter-spacing:0.06em; color:#f3ede2;
    display:flex; align-items:center; gap:6px; white-space:nowrap;
  }
  .nav-cta-text span{opacity:0.5; font-size:10.5px;}
  .nav-arrow{
    width:38px; height:38px; border-radius:50%; background:var(--accent); color:#fff;
    display:flex; align-items:center; justify-content:center; font-size:15px; flex-shrink:0;
    transition:transform .25s, width .3s, height .3s, font-size .3s;
  }
  a.nav-cta:hover .nav-arrow{transform:translateX(3px);}

  /* MENU PANEL — header altindan acilan koyu panel */
  .menu-scrim{
    position:fixed; inset:0; z-index:50; background:rgba(12,9,6,0.42);
    opacity:0; visibility:hidden; transition:opacity .35s ease, visibility .35s;
  }
  .menu-scrim.open{opacity:1; visibility:visible;}
  .menu-panel{
    position:fixed; z-index:56; top:78px; left:24px;
    width:min(660px, calc(100vw - 48px));
    background:#17130f; border:1px solid rgba(243,239,230,0.09); border-radius:10px;
    overflow:hidden; box-shadow:0 26px 60px rgba(10,7,4,0.42);
    opacity:0; visibility:hidden; transform:translateY(-10px) scale(0.985);
    transform-origin:top left; pointer-events:none;
    transition:opacity .38s cubic-bezier(.6,0,.2,1), transform .38s cubic-bezier(.6,0,.2,1), visibility .38s;
  }
  .menu-panel.open{opacity:1; visibility:visible; transform:none; pointer-events:auto;}
  .mp-inner{display:grid; grid-template-columns:0.78fr 1fr; min-height:360px;}
  .mp-left{
    display:flex; flex-direction:column; justify-content:space-between; gap:36px;
    padding:32px 24px 28px 16px;
  }
  .mp-links{display:flex; flex-direction:column; gap:4px;}
  .mp-links a{
    font-family:'Space Grotesk',sans-serif; font-weight:500; font-size:14px;
    letter-spacing:0.13em; text-transform:uppercase; color:rgba(243,239,230,0.88);
    padding:6px 0; display:inline-flex; align-items:center; width:fit-content;
    transition:color .25s, transform .25s;
  }
  .mp-links a:hover, .mp-links a:focus-visible{color:var(--accent); transform:translateX(4px);}
  .mp-card{display:flex; flex-direction:column; align-items:flex-start; gap:11px;}
  .mp-avatar{
    width:60px; height:60px; border-radius:5px; overflow:hidden;
    background:var(--pp) center 22% / cover no-repeat, #2a221b;
    border:1px solid rgba(243,239,230,0.16);
  }
  .mp-name{
    display:flex; align-items:center; gap:9px;
    font-family:'Space Grotesk',sans-serif; font-weight:700; font-size:14.5px;
    letter-spacing:0.055em; text-transform:uppercase; color:#f3efe6;
  }
  .mp-name::before{content:""; width:8px; height:8px; background:var(--accent); flex-shrink:0;}
  .mp-role{
    font-family:'JetBrains Mono',monospace; font-size:10px; letter-spacing:0.12em;
    text-transform:uppercase; color:rgba(243,239,230,0.5);
  }
  .mp-social{display:flex; gap:14px; margin-top:2px;}
  .mp-social a{
    color:rgba(243,239,230,0.5); display:flex; transition:color .25s, transform .25s;
  }
  .mp-social a:hover, .mp-social a:focus-visible{color:var(--accent); transform:translateY(-2px);}
  .mp-social svg{width:15px; height:15px; fill:currentColor;}
  .mp-right{display:grid; grid-template-rows:1fr 1fr; gap:4px; padding:4px 4px 4px 0;}
  .mp-tile{
    position:relative; overflow:hidden; border-radius:7px; display:flex;
    align-items:center; justify-content:center;
    background:radial-gradient(120% 120% at 30% 20%, #3b2a1e 0%, #17130f 72%);
  }
  .mp-tile::after{
    content:""; position:absolute; inset:0;
    background:linear-gradient(180deg, transparent 45%, rgba(10,7,4,0.55) 100%);
  }
  .mp-tile img{
    width:58px; height:58px; object-fit:contain; border-radius:7px; background:#f8f6f1;
    padding:7px; transition:transform .45s cubic-bezier(.6,0,.2,1);
  }
  .mp-tile:hover img, .mp-tile:focus-visible img{transform:scale(1.07);}
  /* Behance kapakli menu tile — gorsel tam kadraj */
  .mp-tile-shot img{
    width:100%; height:100%; object-fit:cover; border-radius:0;
    background:none; padding:0;
  }
  .mp-tile-shot::after{
    background:linear-gradient(180deg, rgba(10,7,4,0) 32%, rgba(10,7,4,0.55) 68%, rgba(10,7,4,0.92) 100%);
  }
  .mp-tile-shot b, .mp-tile-shot em{text-shadow:0 1px 6px rgba(10,7,4,0.5);}
  .mp-tile b{
    position:absolute; z-index:2; left:16px; bottom:14px;
    font-family:'Space Grotesk',sans-serif; font-weight:500; font-size:13px;
    letter-spacing:0.02em; color:#f6f2e9;
  }
  .mp-tile em{
    position:absolute; z-index:2; right:16px; bottom:15px; font-style:normal;
    font-family:'JetBrains Mono',monospace; font-size:9.5px; letter-spacing:0.12em;
    text-transform:uppercase; color:rgba(243,239,230,0.5);
  }
  @media (prefers-reduced-motion: reduce){
    .menu-panel, .menu-scrim, .mp-tile img, .mp-links a{transition:none;}
  }

  /* HERO — full-bleed warm gradient stage, matching reference */
  .hero{
    position:relative; min-height:100vh; overflow:hidden;
    display:flex; flex-direction:column; justify-content:flex-end;
    padding-top:120px;
  }
  .hero-bg{
    position:absolute; inset:-10%;
    background:url("data:image/png;base64,") center 30% / cover no-repeat;
    animation:heroDrift 16s ease-in-out infinite alternate;
    will-change:transform;
  }
  .hero-overlay{
    position:absolute; inset:0;
    background:linear-gradient(155deg, rgba(60,30,15,0.15) 0%, rgba(20,12,8,0.55) 75%);
  }
  @keyframes heroDrift{
    0%{ transform:scale(1.05) translate(0,0) rotate(0deg); }
    100%{ transform:scale(1.32) translate(-4%,-3%) rotate(1.2deg); }
  }
  @media (prefers-reduced-motion: reduce){ .hero-bg{ animation:none; } }
  .hero-bloom{ display:none; }
  .hero-inner{ position:relative; z-index:2; max-width:1720px; margin:0 auto; padding:0 40px; width:100%; }
  .hero-copy{
    display:flex; justify-content:space-between; align-items:flex-end;
    gap:40px; flex-wrap:wrap; margin-bottom:34px;
  }
  .hero-statement{
    font-family:'JetBrains Mono',monospace; font-size:13.5px; letter-spacing:0.02em;
    text-transform:uppercase; color:rgba(243,237,226,0.62); line-height:1.7;
    max-width:400px; margin-bottom:0;
  }
  .hero-statement strong{display:block; color:#f3ede2; font-weight:500;}
  .hero-services{font-family:'JetBrains Mono',monospace; font-size:13px; text-transform:uppercase; color:#f3ede2;}
  .hero-services div{display:flex; gap:14px; padding:5px 0; align-items:baseline;}
  .hero-services span{color:rgba(243,237,226,0.45); font-size:12px;}
  .hero-wordmark{
    font-family:'Space Grotesk',sans-serif; font-weight:700; color:#faf6ee;
    font-size:clamp(90px, 17vw, 240px); line-height:0.85; letter-spacing:-0.02em;
    margin:0 -6px -0.12em 0; white-space:nowrap;
    text-align:right; display:block;
  }
  .hero-wordmark sup{font-size:0.28em; vertical-align:top; top:0.1em; position:relative;}
  .hero-foot{
    display:flex; justify-content:space-between; align-items:flex-end; flex-wrap:wrap; gap:24px;
    padding:26px 0 34px;
  }
  .hero-status{display:none;}
  .hero-brands{display:flex; align-items:center; gap:16px;}
  .brand-stack{display:flex;}
  .brand-badge{
    width:46px; height:46px; border-radius:50%; background:#f8f6f1;
    display:flex; align-items:center; justify-content:center; padding:8px;
    margin-left:-14px; border:2px solid rgba(20,15,10,0.55);
    box-shadow:0 3px 10px rgba(0,0,0,0.3);
  }
  .brand-badge:first-child{margin-left:0;}
  .brand-badge img{max-width:100%; max-height:100%; object-fit:contain;}
  .hero-brands-text{font-family:'JetBrains Mono',monospace; line-height:1.5;}
  .hero-brands-text strong{display:block; color:#f3ede2; font-weight:500; font-size:12.5px; letter-spacing:0.01em;}
  .hero-brands-text span{display:block; color:rgba(243,237,226,0.6); font-size:11px; text-transform:uppercase; letter-spacing:0.06em; margin-top:3px;}

  /* SERITTEKI LOGOLAR — Hanza olculeri: hucre 228x96, logo kutusu 88x32 */
  .mq-group{display:flex; align-items:center; gap:0; flex-shrink:0;}
  .mq-group .lg{
    width:88px; height:32px; padding:32px 70px; box-sizing:content-box; flex-shrink:0;
    background:var(--lg) center/contain no-repeat;
    background-origin:content-box; background-clip:content-box;
    filter:grayscale(1) contrast(0.92); opacity:0.6;
    border-right:1px solid rgba(23,20,15,0.08);
  }
  @media (max-width: 900px){
    .mq-group .lg{width:64px; height:24px; padding:22px 40px;}
  }

  /* MARQUEE */
  .marquee-strip{ border-top:1px solid var(--line); border-bottom:1px solid var(--line); padding:0; overflow:hidden; background:#fcfcfc; }
  .marquee-track{display:flex; gap:0; width:max-content; animation:scroll 54s linear infinite;}
  @keyframes scroll{from{transform:translateX(0);} to{transform:translateX(-50%);}}
  @media (prefers-reduced-motion: reduce){.marquee-track{animation:none;}}

  .section-pad{padding:120px 0;}
  .section-head{
    display:flex; justify-content:space-between; align-items:flex-end;
    gap:40px; margin-bottom:64px; flex-wrap:wrap;
    border-bottom:1px solid var(--line); padding-bottom:26px;
  }
  .section-head h2{font-size:clamp(30px,4vw,46px); font-weight:400;}
  .section-head p{max-width:340px; color:var(--muted); font-size:14.5px;}

  /* ABOUT */
  /* MISYON — Hanza tarzi statement + istatistik */
  .about-col .service-row{
    display:grid; grid-template-columns:44px 1fr auto; align-items:center; gap:18px;
  }
  .about-col .service-row .tag{text-align:right;}
  .about-col .section-head{padding-bottom:18px; margin-bottom:38px;}
  .mission-eyebrow{
    display:flex; align-items:center; justify-content:space-between; gap:24px;
    font-family:'JetBrains Mono',monospace; font-size:12px; letter-spacing:0.08em;
    text-transform:uppercase; color:var(--text);
    padding-bottom:18px; border-bottom:1px solid var(--line); margin-bottom:38px;
  }
  .mission-eyebrow .me-left{display:flex; align-items:center; gap:10px;}
  .mission-eyebrow i{width:7px; height:7px; background:var(--accent); display:block;}
  .mission-eyebrow .me-num{color:var(--muted);}
  .mission-eyebrow .me-right{color:var(--muted); letter-spacing:0.06em;}
  .mission-statement{
    font-family:'Space Grotesk',sans-serif; font-weight:500;
    font-size:clamp(17px,1.8vw,25px); line-height:1.38; letter-spacing:-0.01em;
    color:var(--text); margin-bottom:34px;
  }
  .mission-statement .w{color:rgba(23,20,15,0.22); transition:color .5s ease;}
  .mission-statement .w.on{color:var(--text);}
  .mission-note{color:var(--muted); font-size:16px; line-height:1.6; max-width:640px; margin-bottom:14px;}
  .stat-grid{
    display:grid; grid-template-columns:repeat(2,1fr); gap:1px;
    background:var(--line); border:1px solid var(--line); margin:44px 0 40px;
  }
  .stat{background:var(--bg); padding:26px 24px 30px; position:relative;}
  .stat::before{content:""; position:absolute; top:0; left:0; right:0; height:2px; background:var(--accent);}
  .stat-head{
    display:flex; align-items:center; justify-content:space-between; gap:16px;
    font-family:'JetBrains Mono',monospace; font-size:11.5px; letter-spacing:0.09em;
    text-transform:uppercase;
  }
  .stat-head .sn{color:var(--muted); margin-right:8px;}
  .stat-dots{display:flex; gap:3px;}
  .stat-dots span{width:6px; height:6px; background:var(--line); display:block;}
  .stat-dots span:last-child{background:var(--accent);}
  .stat-num{
    font-family:'Space Grotesk',sans-serif; font-weight:500;
    font-size:clamp(38px,4.2vw,60px); letter-spacing:-0.03em; line-height:1;
    margin:38px 0 14px;
  }
  .stat p{color:var(--muted); font-size:14px; line-height:1.55; max-width:230px;}
  @media (max-width: 640px){
    .stat-grid{grid-template-columns:1fr;}
    .stat-num{margin-top:26px;}
  }
  @media (prefers-reduced-motion: reduce){
    .mission-statement .w{transition:none;}
  }

  /* HAKKIMDA + DENEYIM — yan yana */
  .about-shell{
    display:grid; grid-template-columns:minmax(340px,430px) 1fr;
    gap:clamp(40px,4vw,72px); align-items:start;
  }
  .about-col .stat-grid{grid-template-columns:1fr; margin:40px 0 0;}
  .about-col .stat{padding:20px 22px 24px;}
  .about-col .stat-num{font-size:clamp(34px,3vw,46px); margin:18px 0 10px;}
  .about-col .stat p{max-width:none;}
  .about-col .about-grid{grid-template-columns:1fr; gap:34px;}
  .about-col .about-text p{max-width:none; font-size:16px;}
  .about-col .about-text p:first-child{font-size:19px;}
  .about-col .services{margin-top:34px;}
  .mission-col{min-width:0; padding-top:2px;}
  .exp-col{
    scroll-margin-top:110px; margin-top:clamp(48px,5vw,72px);
  }
  .exp-col .section-head{margin-bottom:10px;}
  .exp-col .exp-row{grid-template-columns:52px 186px 1fr; gap:22px;}
  .exp-col .exp-row:last-child{border-bottom:none;}
  .exp-col .exp-row > p{grid-column:2 / -1; max-width:none; margin-top:-6px;}
  .exp-col .exp-row:hover{border-radius:10px;}
  @media (max-width: 1280px){
    .about-shell{grid-template-columns:1fr; gap:56px;}
    .about-col .stat-grid{grid-template-columns:repeat(3,1fr);}
    .about-col .about-grid{grid-template-columns:minmax(300px,400px) 1fr; gap:clamp(48px,6vw,110px);}
    .about-col .about-text p{max-width:560px;}
  }
  @media (max-width: 900px){
    .exp-col .exp-row{grid-template-columns:1fr;}
  }

  .about-grid{ display:grid; grid-template-columns:minmax(300px,400px) 1fr; gap:clamp(48px,6vw,110px); align-items:start; }
  .about-card{border:1px solid var(--line); background:#fff;}
  .about-portrait{
    position:relative; aspect-ratio:4/5; overflow:hidden;
    border-top:2px solid var(--accent);
  }
  .about-portrait img{width:100%; height:100%; object-fit:cover; object-position:50% 50%; display:block;}
  .ap-cta{
    position:absolute; left:0; right:0; bottom:0; display:flex; align-items:stretch;
  }
  .ap-cta .lbl{
    flex:1; background:#141210; color:#f3efe6; padding:15px 18px;
    font-family:'JetBrains Mono',monospace; font-size:12px; letter-spacing:0.09em; text-transform:uppercase;
    display:flex; align-items:center; gap:8px;
  }
  .ap-cta .lbl b{font-weight:400; color:rgba(243,239,230,0.5);}
  .ap-cta .go{
    width:52px; background:var(--accent); color:#fff; display:flex; align-items:center; justify-content:center;
    font-size:16px; transition:background .25s;
  }
  .ap-cta:hover .go{background:#e64a30;}
  .ap-cta:focus-visible{outline:2px solid var(--accent); outline-offset:2px;}
  .ap-meta{padding:22px 20px 24px;}
  .ap-name{
    display:flex; align-items:center; gap:9px;
    font-family:'Space Grotesk',sans-serif; font-weight:600; font-size:15px;
    letter-spacing:0.06em; text-transform:uppercase;
  }
  .ap-name::before{content:""; width:8px; height:8px; background:var(--accent); flex-shrink:0;}
  .ap-head{display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:22px;}
  .ap-social{display:flex; gap:14px;}
  .ap-social a{color:var(--muted); display:flex; transition:color .25s, transform .25s;}
  .ap-social a:hover, .ap-social a:focus-visible{color:var(--accent); transform:translateY(-2px);}
  .ap-social svg{width:16px; height:16px; fill:currentColor;}
  .ap-row{
    display:flex; align-items:baseline; justify-content:space-between; gap:20px;
    font-family:'JetBrains Mono',monospace; font-size:11.5px; letter-spacing:0.08em; text-transform:uppercase;
    padding:9px 0;
  }
  .ap-row span{color:var(--muted);}
  .ap-row b{font-weight:400; color:var(--text); text-align:right;}
  .about-text p{color:var(--muted); font-size:17px; margin-bottom:20px; max-width:560px;}
  .about-text p:first-child{color:var(--text); font-size:21px; font-family:'Space Grotesk',sans-serif; font-weight:500; letter-spacing:-0.02em; line-height:1.45;}
  .services{margin-top:48px; border-top:1px solid var(--line);}
  .service-row{
    display:flex; justify-content:space-between; align-items:center;
    padding:22px 0; border-bottom:1px solid var(--line);
    font-family:'Space Grotesk',sans-serif; font-size:19px;
  }
  .service-row .num{font-family:'JetBrains Mono',monospace; color:var(--accent); font-size:13px;}
  .service-row .tag{font-family:'JetBrains Mono',monospace; color:var(--muted); font-size:12px;}

  /* PROJECTS — bento grid */
  .bento{display:grid; grid-template-columns:repeat(3,1fr); gap:10px; align-items:start;}
  .bcard{
    position:relative; isolation:isolate; overflow:hidden;
    display:flex; flex-direction:column; justify-content:space-between;
    min-height:0; padding:10px; border-radius:18px; color:#f3ede2;
    background-color:#141110; background-image:none;
    border:1px solid rgba(255,255,255,0.07);
    transition:transform .45s cubic-bezier(.2,.7,.3,1), box-shadow .45s ease;
  }
  /* kapak gorseli — tam kadraj, kirpma yok */
  .bshot{
    display:block; width:100%; aspect-ratio:808/632; overflow:hidden;
    border-radius:12px; background:#0f0d0c;
  }
  .bshot::after{
    content:""; display:block; width:100%; height:100%;
    background:var(--shot, none) center/cover no-repeat;
    transition:transform .7s cubic-bezier(.2,.7,.3,1);
  }
  a.bcard:hover .bshot::after{transform:scale(1.045);}
  a.bcard:hover{transform:translateY(-3px); box-shadow:0 18px 44px rgba(10,8,6,.18);}
  a.bcard:focus-visible{outline:2px solid var(--accent); outline-offset:3px;}
  .bhead{display:flex; align-items:flex-start; justify-content:space-between; gap:16px;}
  /* kapakli kartta eyebrow gizli — kategori bmeta'da zaten var */
  .bcard .bshot ~ .bhead{display:none;}
  .bcard .bshot ~ .bfoot{
    display:block; margin-top:0; padding:16px 62px 8px 8px;
  }
  .blabel{font-family:'JetBrains Mono',monospace; font-size:11.5px; letter-spacing:0.08em;
    text-transform:uppercase; opacity:0.6;}
  .bdots{
    width:15px; height:15px; flex-shrink:0; opacity:0.45;
    background-image:radial-gradient(currentColor 1.1px, transparent 1.2px);
    background-size:6px 6px;
  }
  .btitle{font-size:22px; font-weight:400; margin-top:10px; line-height:1.2;}
  .bshot ~ .bfoot .btitle{margin-top:0; font-size:19px; letter-spacing:-0.01em; min-height:2.4em;}
  .bcard-lg .btitle{font-size:clamp(26px,2.6vw,36px);}
  .bfoot{display:flex; align-items:flex-end; justify-content:space-between; gap:16px; margin-top:36px;}
  .bgo{
    width:44px; height:44px; border-radius:13px; flex-shrink:0;
    background:var(--accent); color:#1a1109;
    display:grid; place-items:center; font-size:17px;
    transition:transform .3s, border-radius .3s;
  }
  /* kapakli kartta turuncu ok sag alt kose */
  .bshot ~ .bfoot .bgo{position:absolute; right:12px; bottom:12px; margin:0;}
  .bshot ~ .bfoot .bmeta{display:block; text-align:left; margin-top:9px; line-height:1.5;}
  a.bcard:hover .bgo{transform:translateX(5px); border-radius:22px;}
  .bmeta{font-family:'JetBrains Mono',monospace; font-size:11.5px; letter-spacing:0.06em;
    opacity:0.55; text-align:right;}
  .bcard-lg{grid-column:span 2; min-height:0;}
  .bcard-tall{min-height:460px;}
  .bcard-wide{grid-column:span 2; min-height:0;}
  .bcard-lg .bshot, .bcard-wide .bshot{aspect-ratio:16/9;}
  .bcard-lg .bshot ~ .bfoot .btitle{font-size:clamp(22px,2vw,28px);}
  /* accent bilgi karti */
  .bcard-accent, .bcard-cta{padding:24px; border-color:transparent;}
  .bcard-accent{background:var(--accent); background-image:none; color:#fff;}
  .bcard-accent::before, .bcard-accent::after{display:none;}
  .bcard-accent .bmesh{
    height:96px; margin:22px 0;
    background-image:radial-gradient(rgba(255,255,255,.65) 1.3px, transparent 1.4px);
    background-size:38px 24px;
  }
  .bcard-accent h3{font-size:clamp(20px,1.7vw,26px); font-weight:400; line-height:1.25; margin-top:10px;}
  .bcard-accent p{font-size:14px; line-height:1.55; opacity:0.88; margin-top:12px;}
  .bcard-accent .bmeta{opacity:0.8; text-align:left;}
  /* CTA karti */
  .bcard-cta{background:var(--surface); background-image:none; color:var(--text);}
  .bcard-cta::before, .bcard-cta::after{display:none;}
  .bcard-cta .blabel{opacity:0.5;}
  .bcard-cta h3{font-size:clamp(22px,2vw,30px); font-weight:400; line-height:1.2; margin-top:10px;}
  .placeholder-note{
    margin-top:28px; font-family:'JetBrains Mono',monospace; font-size:12px; color:var(--muted);
    border-left:2px solid var(--accent); padding-left:14px;
  }
  @media (max-width: 1020px){
    .bento{grid-template-columns:repeat(2,1fr);}
    .bcard-lg, .bcard-wide{grid-column:span 2;}
    .bcard-tall{min-height:360px;}
  }
  @media (max-width: 680px){
    .bento{grid-template-columns:1fr;}
    .bcard-lg, .bcard-wide{grid-column:span 1;}
    .bcard{min-height:0; padding:10px;}
    .bcard-accent, .bcard-cta{padding:20px; min-height:260px;}
    .bcard-tall{min-height:320px;}
    .bcard-lg .bshot, .bcard-wide .bshot{aspect-ratio:808/632;}
  }
  @media (prefers-reduced-motion: reduce){
    .bcard, .bshot::after, .bgo{transition:none;}
  }

  /* PROCESS */
  .process-list{border-top:1px solid var(--line);}
  .process-row{ display:grid; grid-template-columns:80px 1fr 1.4fr; gap:32px; padding:36px 0; border-bottom:1px solid var(--line); }
  .process-row .pnum{font-family:'JetBrains Mono',monospace; color:var(--accent); font-size:14px;}
  .process-row h4{font-size:22px; font-weight:400; margin-bottom:8px;}
  .process-row p{color:var(--muted); font-size:14.5px; max-width:460px;}

  /* DENEYIM */
  .exp-list{border-top:1px solid var(--line);}
  .exp-row{
    display:grid; grid-template-columns:56px 138px 1fr 1.2fr; gap:28px;
    padding:32px 0; border-bottom:1px solid var(--line);
    transition:background .25s, padding-left .3s;
  }
  .exp-logo{
    width:56px; height:56px; border:1px solid var(--line); border-radius:6px;
    background:var(--lg) center/68% no-repeat, #fff;
    display:flex; align-items:center; justify-content:center;
  }
  .exp-logo.exp-mono{
    background:#f3f2f0; font-family:'Space Grotesk',sans-serif; font-weight:700;
    font-size:19px; color:var(--muted); letter-spacing:0.02em;
  }
  .exp-row:hover{background:var(--accent-soft); padding-left:14px;}
  .exp-when{font-family:'JetBrains Mono',monospace; font-size:12.5px; color:var(--accent); line-height:1.6;}
  .exp-when span{display:block; color:var(--muted); font-size:11px; letter-spacing:0.06em; text-transform:uppercase; margin-top:4px;}
  .exp-role h4{font-size:21px; font-weight:400; margin-bottom:6px;}
  .exp-role .co{font-size:14.5px; color:var(--text);}
  .exp-role .meta{
    font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--muted);
    text-transform:uppercase; letter-spacing:0.08em; margin-top:8px;
  }
  .exp-row p{color:var(--muted); font-size:14.5px; max-width:460px;}
  @media (max-width: 900px){
    .exp-row{grid-template-columns:44px 1fr; gap:14px 16px; padding:26px 0;}
    .exp-row > :nth-child(n+3){grid-column:1 / -1;}
    .exp-logo{width:44px; height:44px;}
  }

  /* BLOG */
  .blog-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:26px;}
  .blog-card{border:1px solid var(--line); border-radius:14px; overflow:hidden; transition:border-color .25s, transform .25s; background:var(--bg-alt);}
  .blog-card:hover{border-color:var(--accent); transform:translateY(-4px);}
  .blog-thumb{aspect-ratio:16/10; background:linear-gradient(135deg,#f0efec,#dedcd6);}
  .blog-body{padding:22px 22px 26px;}
  .blog-tag{font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--accent); text-transform:uppercase; letter-spacing:0.08em;}
  .blog-body h4{font-size:19px; font-weight:400; margin:12px 0 8px; font-family:'Space Grotesk',sans-serif;}
  .blog-body p{color:var(--muted); font-size:13.5px;}

  /* CONTACT — Hanza duzeni: etiket satiri + alan satiri, tam genislik ince cizgiler */
  .contact-grid{display:grid; grid-template-columns:minmax(280px,380px) 1fr; gap:clamp(40px,5vw,90px);}
  .contact-info h2{font-size:clamp(30px,3.6vw,46px); font-weight:500; letter-spacing:-0.025em; max-width:420px; margin-bottom:22px;}
  .contact-info p{color:var(--mut, var(--muted)); max-width:360px; margin-bottom:34px;}
  .contact-detail{margin-bottom:18px;}
  .contact-detail .label{
    font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--muted);
    text-transform:uppercase; letter-spacing:0.12em; display:flex; align-items:center; gap:8px; margin-bottom:6px;
  }
  .contact-detail .label::before{content:""; width:6px; height:6px; background:var(--accent); flex-shrink:0;}
  .contact-detail .val{font-size:16.5px;}

  .cf{display:block; border-top:1px solid var(--line);}
  .cf-row{border-bottom:1px solid var(--line); padding:16px 0 18px;}
  .cf-lbl{
    display:flex; align-items:center; gap:8px;
    font-family:'JetBrains Mono',monospace; font-size:11.5px; letter-spacing:0.1em;
    text-transform:uppercase; color:var(--muted); margin-bottom:12px;
  }
  .cf-lbl::before{content:""; width:6px; height:6px; background:var(--accent); flex-shrink:0;}
  .cf input, .cf textarea{
    width:100%; background:none; border:none; outline:none; resize:vertical;
    font-family:'Space Grotesk',sans-serif; font-size:16px; color:var(--text); line-height:1.5;
  }
  .cf input::placeholder, .cf textarea::placeholder{color:rgba(111,106,92,0.45);}
  .cf input:focus-visible, .cf textarea:focus-visible{outline:none;}
  .cf-row:focus-within{border-bottom-color:var(--accent);}
  .cf-send{display:flex; align-items:center; justify-content:space-between; gap:24px; flex-wrap:wrap; padding-top:26px;}
  .cf-btn{
    display:flex; align-items:stretch; border:none; padding:0; cursor:pointer; background:none;
    min-width:320px;
  }
  .cf-btn .cf-state{
    flex:1; background:#141210; color:#f3efe6; display:flex; align-items:center; padding:0 22px;
    font-family:'JetBrains Mono',monospace; font-size:12px; letter-spacing:0.11em; text-transform:uppercase;
    min-height:52px; transition:background .25s;
  }
  .cf-btn .cf-go{
    width:56px; min-height:52px; background:var(--accent); color:#fff;
    display:flex; align-items:center; justify-content:center; font-size:16px; transition:background .25s;
  }
  .cf-btn[disabled]{cursor:not-allowed;}
  .cf-btn[disabled] .cf-state{background:#8b8781;}
  .cf-btn[disabled] .cf-go{background:#b9b5ae;}
  .cf-btn:not([disabled]):hover .cf-go{background:#e64a30;}
  .cf-btn:focus-visible{outline:2px solid var(--accent); outline-offset:3px;}
  .cf-note{
    font-family:'JetBrains Mono',monospace; font-size:11px; letter-spacing:0.06em;
    color:var(--muted); max-width:280px; text-align:right; margin-left:auto;
  }
  @media (max-width: 900px){
    .cf-btn{min-width:100%;}
    .cf-note{text-align:left; margin-left:0;}
  }

  /* FOOTER */
  footer{border-top:1px solid var(--line); padding:70px 0 40px; background:var(--bg-alt);}
  .footer-top{display:flex; justify-content:space-between; flex-wrap:wrap; gap:40px; padding-bottom:50px;}
  .footer-cols{display:flex; gap:70px; flex-wrap:wrap;}
  .footer-col .label{font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--muted); text-transform:uppercase; letter-spacing:0.1em; margin-bottom:16px; display:block;}
  .footer-col a, .footer-col span{display:block; font-size:14.5px; margin-bottom:10px; color:var(--muted); transition:color .25s;}
  .footer-col a:hover{color:var(--accent);}
  .footer-bottom{
    display:flex; justify-content:space-between; padding-top:26px; border-top:1px solid var(--line);
    font-family:'JetBrains Mono',monospace; font-size:12px; color:var(--muted); flex-wrap:wrap; gap:12px;
  }

  .reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}
  .reveal.in{opacity:1; transform:translateY(0);}
  @media (prefers-reduced-motion: reduce){.reveal{opacity:1; transform:none; transition:none;}}

  @media (max-width: 900px){
    .nav-cta{display:none;}
    .about-grid, .contact-grid{grid-template-columns:1fr; gap:48px;}
    .process-row{grid-template-columns:1fr;}
    .blog-grid{grid-template-columns:1fr;}
    .hero{padding:140px 0 70px;}
    .wrap{padding:0 20px;}
    nav{padding:20px;}
    .hero-inner{padding:0 20px;}
    .menu-panel{top:72px; left:14px; width:calc(100vw - 28px); max-height:calc(100vh - 92px); overflow-y:auto;}
    .mp-inner{grid-template-columns:1fr; min-height:0;}
    .mp-left{padding:26px 20px 24px 14px; gap:28px;}
    .mp-right{grid-template-rows:1fr; padding:0 14px 16px;}
    .mp-right .mp-tile:last-child{display:none;}
    .mp-tile{aspect-ratio:16/7;}
  }
/* ==== ALT SAYFALAR ==== */
  /* aktif menu ogesi */
  .nav-mid a.active{opacity:1; color:var(--accent);}
  .mp-links a.active{color:var(--accent);}

  /* sayfa basligi */
  .page-hero{
    padding:150px 0 60px;
    border-bottom:1px solid var(--line);
    background:var(--bg-alt);
  }
  .ph-crumb{
    font-family:'JetBrains Mono',monospace; font-size:11.5px;
    letter-spacing:0.1em; text-transform:uppercase; color:var(--muted);
    display:flex; align-items:center; gap:9px; margin-bottom:34px;
  }
  .ph-crumb a{color:var(--muted); transition:color .25s;}
  .ph-crumb a:hover{color:var(--accent);}
  .ph-crumb b{font-weight:500; color:var(--text);}
  .ph-top{
    display:grid; grid-template-columns:1fr minmax(280px,420px);
    gap:40px; align-items:end;
  }
  .ph-eyebrow{
    font-family:'JetBrains Mono',monospace; font-size:12px;
    letter-spacing:0.14em; text-transform:uppercase; color:var(--accent);
    margin-bottom:16px;
  }
  .ph-title{
    font-size:clamp(46px,8.5vw,132px); line-height:0.9;
    letter-spacing:-0.045em; font-weight:500;
  }
  .ph-lead{color:var(--muted); font-size:17px; line-height:1.6; padding-bottom:10px;}

  /* filtre seridi */
  .filter-bar{
    display:flex; align-items:center; justify-content:space-between;
    gap:24px; flex-wrap:wrap; margin-top:52px;
    padding-top:26px; border-top:1px solid var(--line);
  }
  .pills{display:flex; gap:8px; flex-wrap:wrap;}
  .pill{
    font-family:'JetBrains Mono',monospace; font-size:11.5px;
    letter-spacing:0.09em; text-transform:uppercase; cursor:pointer;
    padding:9px 17px; border-radius:var(--radius);
    border:1px solid var(--line); background:transparent; color:var(--muted);
    transition:background-color .25s, color .25s, border-color .25s;
  }
  .pill:hover{color:var(--text); border-color:var(--text);}
  .pill.on{background:var(--text); border-color:var(--text); color:var(--bg);}
  .pill:focus-visible{outline:2px solid var(--accent); outline-offset:2px;}
  .filter-note{
    font-family:'JetBrains Mono',monospace; font-size:11.5px;
    letter-spacing:0.1em; text-transform:uppercase; color:var(--muted);
    display:flex; align-items:center; gap:7px;
  }
  .bcard.gizli{display:none;}

  /* bolum basligindaki "tumunu gor" */
  .section-head{position:relative;}
  .sec-more{
    display:inline-flex; align-items:center; gap:8px; margin-top:18px;
    font-family:'JetBrains Mono',monospace; font-size:11.5px;
    letter-spacing:0.1em; text-transform:uppercase; color:var(--muted);
    border-bottom:1px solid var(--line); padding-bottom:4px;
    transition:color .25s, border-color .25s;
  }
  .sec-more:hover{color:var(--accent); border-color:var(--accent);}

  /* sayfa alti gecis seridi */
  .next-strip{border-top:1px solid var(--line); padding-top:0;}
  .next-link{
    display:flex; align-items:center; gap:22px; padding:44px 0;
    transition:color .25s;
  }
  .next-link .nl-lbl{
    font-family:'JetBrains Mono',monospace; font-size:11.5px;
    letter-spacing:0.12em; text-transform:uppercase; color:var(--muted);
  }
  .next-link .nl-title{
    font-size:clamp(30px,4.5vw,58px); letter-spacing:-0.035em;
    font-weight:500; margin-right:auto;
  }
  .next-link .nl-go{
    width:52px; height:52px; flex:0 0 52px; border-radius:50%;
    border:1px solid var(--line); display:grid; place-items:center;
    transition:background-color .25s, color .25s, border-color .25s, transform .25s;
  }
  .next-link:hover .nl-title{color:var(--accent);}
  .next-link:hover .nl-go{background:var(--accent); border-color:var(--accent); color:#fff; transform:translateX(5px);}

  /* deneyim sayfasi: tam genislik */
  .exp-col.exp-wide{max-width:1240px; margin:0 auto;}
  .exp-col.exp-wide .exp-row{grid-template-columns:64px 230px 1fr; gap:26px;}
  .exp-col.exp-wide .exp-row > p{max-width:760px;}
  @media (max-width:900px){ .exp-col.exp-wide .exp-row{grid-template-columns:1fr;} }

  /* hakkimda sayfasinda ust bosluk azalir */
  .page-section{padding-top:74px;}

  @media (max-width:1000px){
    .ph-top{grid-template-columns:1fr; align-items:start; gap:24px;}
    .ph-lead{padding-bottom:0;}
    .page-hero{padding:120px 0 48px;}
  }
  @media (max-width:640px){
    .filter-note{display:none;}
    .next-link{gap:14px;}
  }

/* ==== BEHANCE KARTLARI ==== */
  /* 6 proje + tam genislik CTA */
  .bcard-cta{grid-column:span 3; min-height:210px;}
  /* projeler.html tam liste */
  .bento-liste .bcard{min-height:0;}
  .bento-liste .bcard-cta{display:none;}
  @media (max-width:1020px){ .bcard-cta{grid-column:span 2;} }
  @media (max-width:680px){ .bcard-cta{grid-column:span 1;} }

/* ==== PROJELER — SEVORA TARZI 3'LU GRID ==== */
  .bento-sevora{
    grid-template-columns:repeat(3,1fr);
    column-gap:28px; row-gap:52px;
  }
  .bento-sevora .bcard{
    padding:0; border:0; border-radius:0; overflow:visible;
    background:none; background-color:transparent;
    color:var(--text); display:block; min-height:0;
  }
  .bento-sevora a.bcard:hover{transform:none; box-shadow:none;}
  .bento-sevora .bshot{
    aspect-ratio:1.32; border-radius:20px; background:var(--surface);
    box-shadow:none; border:0;
  }
  .bento-sevora a.bcard:hover .bshot::after{transform:scale(1.05);}
  .bento-sevora .bcard .bshot ~ .bfoot{
    display:flex; align-items:flex-start; justify-content:space-between;
    gap:20px; padding:18px 2px 0; margin-top:0;
  }
  .bento-sevora .bshot ~ .bfoot > div{display:block;}
  .bento-sevora .bshot ~ .bfoot .btitle{
    font-size:19px; font-weight:500; line-height:1.25;
    letter-spacing:-0.015em; min-height:0; margin:0; color:var(--text);
  }
  .bento-sevora .bshot ~ .bfoot .bmeta{
    margin-top:6px; opacity:1; color:var(--muted);
