/* ==== HIZMETLER — LISTE + IZOMETRIK SAHNE ==== */
  .svc-sec{border-top:1px solid var(--line); background:var(--bg); overflow:hidden;}
  .svc-head{max-width:680px; margin:0 auto 56px; text-align:center;}
  .svc-eyebrow{
    display:inline-flex; align-items:center; gap:10px; margin-bottom:18px;
    font-family:'JetBrains Mono',monospace; font-size:11.5px;
    letter-spacing:0.09em; text-transform:uppercase; color:var(--text);
  }
  .svc-eyebrow i{width:7px; height:7px; background:var(--accent); display:block;}
  .svc-eyebrow span{color:var(--muted);}
  .svc-head h2{
    font-size:clamp(28px,3.6vw,48px); font-weight:500;
    letter-spacing:-0.035em; line-height:1.08;
  }
  .svc-head p{color:var(--muted); font-size:16px; line-height:1.65; margin-top:16px;}

  .svc-shell{display:grid; grid-template-columns:1fr 1.1fr; gap:clamp(28px,3.5vw,56px); align-items:start;}

  .svc-list{display:flex; flex-direction:column; gap:6px;}
  .svc-item{
    position:relative; display:flex; gap:16px; text-align:left;
    padding:22px 24px; border:1px solid transparent; border-radius:18px;
    background:transparent; color:var(--text); cursor:pointer;
    font:inherit; width:100%;
    transition:background .4s ease, border-color .4s ease, box-shadow .4s ease, transform .4s cubic-bezier(.2,.7,.3,1);
  }
  .svc-item:hover{background:var(--bg-alt);}
  .svc-item.on{
    background:var(--bg); border-color:var(--line);
    box-shadow:0 2px 4px rgba(23,20,15,.04), 0 16px 40px rgba(23,20,15,.09);
    transform:translateY(-2px);
  }
  .svc-ico{
    width:38px; height:38px; flex-shrink:0; border-radius:11px;
    display:grid; place-items:center; color:var(--muted);
    border:1px solid var(--line); background:var(--bg);
    transition:background .4s ease, color .4s ease, border-color .4s ease;
  }
  .svc-ico svg{width:19px; height:19px; display:block;}
  .svc-item.on .svc-ico{background:var(--text); border-color:var(--text); color:var(--bg);}
  .svc-txt{display:block; min-width:0;}
  .svc-txt b{
    display:block; font-size:19px; font-weight:500;
    letter-spacing:-0.015em; line-height:1.3;
  }
  .svc-txt em{
    display:block; font-style:normal; color:var(--muted);
    font-size:14.5px; line-height:1.6; margin-top:8px; max-width:44ch;
  }

  /* sahne */
  .svc-stage{
    position:relative; border:1px solid var(--line); border-radius:20px;
    background:linear-gradient(180deg,var(--bg-alt),var(--bg));
    min-height:520px; display:flex; flex-direction:column;
    justify-content:center; overflow:hidden;
  }
  .svc-stage::before{
    content:""; position:absolute; inset:0; pointer-events:none;
    background-image:linear-gradient(var(--line) 1px, transparent 1px),
                     linear-gradient(90deg, var(--line) 1px, transparent 1px);
    background-size:44px 44px; opacity:.35;
    -webkit-mask-image:radial-gradient(120% 90% at 50% 45%, #000 25%, transparent 75%);
            mask-image:radial-gradient(120% 90% at 50% 45%, #000 25%, transparent 75%);
  }
  .svc-iso{
    position:relative; width:300px; height:340px; margin:34px auto 0;
    transform-style:preserve-3d;
  }
  .iso-layer{
    position:absolute; left:0; top:0; width:300px; height:190px;
    padding:18px 20px; box-sizing:border-box;
    background:var(--bg); border:1px solid var(--line); border-radius:10px;
    box-shadow:0 18px 34px rgba(23,20,15,.10);
    transform:rotateX(56deg) rotateZ(-45deg) translateZ(0);
    transition:transform .7s cubic-bezier(.2,.7,.3,1), border-color .5s ease;
  }
  .iso-1{transform:rotateX(56deg) rotateZ(-45deg) translate3d(0,0,120px);}
  .iso-2{transform:rotateX(56deg) rotateZ(-45deg) translate3d(0,0,60px); opacity:.92;}
  .iso-3{transform:rotateX(56deg) rotateZ(-45deg) translate3d(0,0,0); opacity:.84;}
  .svc-stage:hover .iso-1{transform:rotateX(56deg) rotateZ(-45deg) translate3d(0,0,150px);}
  .svc-stage:hover .iso-3{transform:rotateX(56deg) rotateZ(-45deg) translate3d(0,0,-24px);}

  .il-line{display:block; height:8px; border-radius:4px; background:var(--surface); margin-bottom:10px;}
  .il-w40{width:40%;} .il-w45{width:45%;} .il-w55{width:55%;} .il-w60{width:60%;} .il-w70{width:70%;}
  .il-grid{display:grid; grid-template-columns:repeat(4,1fr); gap:8px; margin-top:14px;}
  .il-grid i{display:block; height:34px; border-radius:6px; background:var(--surface);}
  .il-shot{display:block; height:74px; border-radius:8px; background:var(--line); opacity:.55; margin:12px 0;}
  .il-tag{
    display:inline-grid; place-items:center; width:38px; height:38px;
    border:1px solid var(--line); border-radius:9px; font-size:15px; margin-bottom:14px;
