  .il-sw{display:flex; gap:7px; margin-bottom:14px;}
  .il-sw i{display:block; width:26px; height:26px; border-radius:7px; border:1px solid var(--line);}

  .svc-stage-foot{
    position:relative; margin-top:auto; display:flex; align-items:center;
    justify-content:space-between; gap:20px;
    padding:18px 22px; border-top:1px solid var(--line); background:var(--bg);
    font-family:'JetBrains Mono',monospace; font-size:10.5px;
    letter-spacing:0.08em; text-transform:uppercase;
  }
  .ssf-label{color:var(--muted);}
  .ssf-value{color:var(--text); text-align:right;}

  /* gorunume gore vurgu */
  .svc-stage[data-view="marka"] .iso-1{border-color:var(--accent);}
  .svc-stage[data-view="web"] .iso-2{border-color:var(--accent); opacity:1;}
  .svc-stage[data-view="art"] .iso-3{border-color:var(--accent); opacity:1;}

  @media (max-width:980px){
    .svc-shell{grid-template-columns:1fr;}
