/* koyu bolumde eyebrow */
  .sec-dark .svc-eyebrow{color:#f3ede2; margin-bottom:14px;}
  .sec-dark .svc-eyebrow span{color:rgba(243,237,226,0.55);}

/* hakkimda bolum etiketi */
  #hakkimda > .wrap > .svc-eyebrow{margin-bottom:30px;}
  /* acik zeminli bolumlerde sade baslik satiri */
  #blog .section-head{border-bottom:0; padding-bottom:0; margin-bottom:44px;}

/* projeler ızgarasının altındaki "tümünü gör" */
  .sec-more-wrap{display:flex; justify-content:flex-end; margin-top:36px;}
  .prc-sec .sec-more-wrap{margin-top:44px;}
  .sec-dark .sec-more-wrap .sec-more{
    color:rgba(243,237,226,0.75); border-color:rgba(255,255,255,0.22); margin-top:0;
  }
  .sec-dark .sec-more-wrap .sec-more:hover{color:var(--accent); border-color:var(--accent);}

/* ==== SUREC — KOYU KADEMELI KARTLAR ==== */
  .prc-sec{border-top:0;}
  /* tam ekran genisligi — wrap disina tasar */
  .prc-grid{
    display:grid; grid-template-columns:repeat(6,1fr);
    gap:0; align-items:start;
    width:auto; margin-left:0;
    border-left:1px solid rgba(255,255,255,0.08);
    border-right:1px solid rgba(255,255,255,0.08);
    border-top:1px solid rgba(255,255,255,0.08);
  }
  /* merdiven — her kutu bir oncekinden asagida, sag kose en altta */
  .prc-grid > *:nth-child(1){margin-top:0;}
  .prc-grid > *:nth-child(2){margin-top:34px;}
  .prc-grid > *:nth-child(3){margin-top:68px;}
  .prc-grid > *:nth-child(4){margin-top:102px;}
  .prc-grid > *:nth-child(5){margin-top:136px;}
  .prc-grid > *:nth-child(6){margin-top:170px;}

  .prc-card{
    position:relative; display:flex; flex-direction:column; justify-content:space-between;
    min-height:440px; padding:22px 20px 26px; text-decoration:none;
    background:#141110;
    border:0; border-right:1px solid rgba(255,255,255,0.08);
    border-bottom:1px solid rgba(255,255,255,0.08);
    color:#f3ede2;
    transition:background .5s ease;
  }
  .prc-grid > *:nth-child(6){border-right:0;}
  .prc-card::before{
    content:""; position:absolute; left:0; right:0; top:0; height:2px;
    background:var(--accent);
  }
  .prc-card:hover{background:#1a1614;}

  .prc-top{display:flex; align-items:flex-start; justify-content:space-between; gap:16px;}
  .prc-num{
    font-family:'Space Grotesk',sans-serif; font-weight:500;
    font-size:clamp(28px,2.4vw,36px); letter-spacing:-0.03em; line-height:1;
  }
  .prc-dots{display:flex; gap:4px; margin-top:8px;}
  .prc-dots i{width:7px; height:7px; display:block; background:rgba(243,237,226,0.22);}
  .prc-dots i.on{background:var(--accent);}

  .prc-lbl{
    display:flex; align-items:center; gap:8px; margin-bottom:14px;
    font-family:'JetBrains Mono',monospace; font-size:10.5px;
    letter-spacing:0.1em; text-transform:uppercase; color:rgba(243,237,226,0.75);
  }
  .prc-lbl i{width:6px; height:6px; background:var(--accent); display:block;}
  .prc-body h3{
    font-size:clamp(17px,1.4vw,21px); font-weight:500;
    letter-spacing:-0.02em; line-height:1.25;
  }
  .prc-body p{
    color:rgba(243,237,226,0.6); font-size:13px; line-height:1.6; margin-top:11px;
  }

  /* CTA karti */
  .prc-cta{background:var(--accent); border-color:var(--accent); color:#fff;}
  .prc-cta::before{background:rgba(255,255,255,0.35);}
  .prc-cta:hover{background:#ff714f; border-color:#ff714f;}
  .prc-cta .prc-body h3{font-size:clamp(23px,2.2vw,30px); font-weight:400;}
  .prc-cta .prc-body h3 b{font-weight:600;}
  .prc-cta .prc-body p{color:rgba(255,255,255,0.85);}
  .prc-go{
    width:38px; height:38px; border-radius:50%; display:grid; place-items:center;
    border:1px solid rgba(255,255,255,0.45); font-size:15px;
    transition:background .3s, color .3s, transform .3s;
  }
  .prc-cta:hover .prc-go{background:#fff; color:var(--accent); transform:translateX(3px);}

  @media (max-width:1240px){
    .prc-grid{grid-template-columns:repeat(3,1fr);}
    .prc-grid > *{margin-top:0;}
    .prc-grid > *:nth-child(3n+2){margin-top:44px;}
    .prc-grid > *:nth-child(3n+3){margin-top:88px;}
    .prc-grid > *:nth-child(3n){border-right:0;}
    .prc-grid > *:nth-child(6){border-right:0;}
    .prc-card{min-height:360px;}
  }
  @media (max-width:840px){
    .prc-grid{grid-template-columns:repeat(2,1fr);}
    .prc-grid > *{margin-top:0;}
    .prc-grid > *:nth-child(2n){margin-top:40px; border-right:0;}
    .prc-grid > *:nth-child(2n+1){border-right:1px solid rgba(255,255,255,0.08);}
  }
  @media (max-width:600px){
    .prc-grid{grid-template-columns:1fr;}
    .prc-grid > *{margin-top:0 !important; border-right:0 !important;}
    .prc-card{min-height:0; padding:22px 20px 24px;}
    .prc-body{margin-top:48px;}
  }

/* ==== SUREC — CREATIVE KATMAN ==== */
  .prc-card{overflow:hidden;}

  /* ust cizgi artik ilerleme cubugu: 01 = 1/6 ... 06 = 6/6 */
  .prc-card::before{
    width:auto; right:auto;
    transition:width .6s cubic-bezier(.2,.7,.3,1), background .4s ease;
  }
  .prc-grid > *:nth-child(1)::before{width:16.66%;}
  .prc-grid > *:nth-child(2)::before{width:33.33%;}
  .prc-grid > *:nth-child(3)::before{width:50%;}
  .prc-grid > *:nth-child(4)::before{width:66.66%;}
  .prc-grid > *:nth-child(5)::before{width:83.33%;}
  .prc-grid > *:nth-child(6)::before{width:100%;}
  .prc-card:hover::before{width:100%;}

  /* hayalet numara — kartin dibinde dev filigran */
  .prc-card::after{
    content:attr(data-n); position:absolute; right:-14px; bottom:-34px;
    font-family:'Space Grotesk',sans-serif; font-weight:600;
    font-size:150px; line-height:1; letter-spacing:-0.06em;
    color:transparent; -webkit-text-stroke:1px rgba(243,237,226,0.09);
    pointer-events:none;
    transition:transform .7s cubic-bezier(.2,.7,.3,1), -webkit-text-stroke-color .5s ease;
  }
  .prc-card:hover::after{
    transform:translate(-6px,-10px);
    -webkit-text-stroke-color:rgba(255,96,68,0.30);
  }

  /* ust satir: numara + toplam */
  .prc-num{position:relative; z-index:1;}
  .prc-num::after{
    content:"/06"; font-family:'JetBrains Mono',monospace;
    font-size:10.5px; letter-spacing:0.08em; color:rgba(243,237,226,0.35);
    margin-left:6px; vertical-align:top;
  }
  .prc-cta .prc-num::after{color:rgba(255,255,255,0.55);}

  .prc-dots i{transition:background .35s ease, transform .35s ease;}
  .prc-card:hover .prc-dots i{background:var(--accent);}
  .prc-card:hover .prc-dots i:nth-child(odd){transform:translateY(-2px);}

  /* icerik hover hareketi */
  .prc-body{position:relative; z-index:1; transition:transform .55s cubic-bezier(.2,.7,.3,1);}
  .prc-card:hover .prc-body{transform:translateY(-5px);}
  .prc-body p{transition:color .4s ease;}
  .prc-card:hover .prc-body p{color:rgba(243,237,226,0.82);}

  /* etiketin karesi hover'da cizgiye uzar */
  .prc-lbl i{transition:width .4s cubic-bezier(.2,.7,.3,1), background .4s ease;}
  .prc-card:hover .prc-lbl i{width:20px;}

  /* CTA kartina capraz doku */
  .prc-cta{position:relative; overflow:hidden;}
  .prc-cta .prc-body, .prc-cta .prc-top{position:relative; z-index:1;}
  .prc-cta::after{
    content:attr(data-n); right:-14px; bottom:-34px;
    -webkit-text-stroke:1px rgba(255,255,255,0.28);
  }
  .prc-cta:hover::after{-webkit-text-stroke-color:rgba(255,255,255,0.5);}
  .prc-cta .prc-mesh{
    position:absolute; inset:0; opacity:.16; pointer-events:none;
    background-image:repeating-linear-gradient(-45deg,#fff 0 1px,transparent 1px 9px);
  }

  @media (max-width:600px){
    .prc-card::after{font-size:110px; bottom:-24px;}
  }
  @media (prefers-reduced-motion: reduce){
    .prc-card::before, .prc-card::after, .prc-body, .prc-dots i, .prc-lbl i{transition:none;}
  }

/* hover — kart turuncu versiyona doner */
  .prc-card:not(.prc-cta){transition:background .45s ease, color .45s ease;}
  .prc-card:not(.prc-cta):hover{background:var(--accent); color:#fff;}
  .prc-card:not(.prc-cta):hover::before{background:rgba(255,255,255,0.45);}
  .prc-card:not(.prc-cta):hover::after{-webkit-text-stroke-color:rgba(255,255,255,0.30);}
  .prc-card:not(.prc-cta):hover .prc-num::after{color:rgba(255,255,255,0.6);}
  .prc-card:not(.prc-cta):hover .prc-dots i{background:rgba(255,255,255,0.35);}
  .prc-card:not(.prc-cta):hover .prc-dots i.on{background:#fff;}
  .prc-card:not(.prc-cta):hover .prc-lbl{color:rgba(255,255,255,0.9);}
  .prc-card:not(.prc-cta):hover .prc-lbl i{background:#fff;}
  .prc-card:not(.prc-cta):hover .prc-body p{color:rgba(255,255,255,0.85);}

/* ==== BLOG KARTLARI — EDITORYAL ==== */
  .blog-grid{gap:0; border-top:1px solid var(--line);}
  .blog-card{
    display:flex; flex-direction:column; justify-content:space-between;
    min-height:290px; padding:26px 26px 24px;
    border:0; border-right:1px solid var(--line); border-bottom:1px solid var(--line);
    border-radius:0; background:var(--bg); overflow:hidden;
    transition:background .45s ease;
  }
  .blog-grid > *:last-child{border-right:0;}
  .blog-card:hover{border-color:var(--line); transform:none; background:var(--bg);}
  .blog-card::before{
    content:""; position:absolute; left:0; top:0; height:2px; width:0;
    background:var(--accent); transition:width .55s cubic-bezier(.2,.7,.3,1);
  }
  .blog-card{position:relative;}
  .blog-card:hover::before{width:100%;}

  .blog-top{display:flex; align-items:center; justify-content:space-between; gap:16px;}
  .blog-tag{color:var(--accent); font-size:10.5px; letter-spacing:0.1em;}
  .blog-ix{
    font-family:'JetBrains Mono',monospace; font-size:10.5px;
    letter-spacing:0.08em; color:var(--muted);
  }
  .blog-body{padding:0; margin-top:38px;}
  .blog-body h4{
    font-size:clamp(19px,1.8vw,24px); font-weight:500; margin:0;
    letter-spacing:-0.02em; line-height:1.25;
  }
  .blog-body p{
    color:var(--muted); font-size:14px; line-height:1.6; margin-top:12px;
  }
  .blog-foot{
    display:flex; align-items:center; justify-content:space-between; gap:16px;
    margin-top:26px; padding-top:16px; border-top:1px solid var(--line);
    font-family:'JetBrains Mono',monospace; font-size:10px;
    letter-spacing:0.08em; text-transform:uppercase; color:var(--muted);
  }
  .blog-go{
    width:30px; height:30px; border-radius:50%; display:grid; place-items:center;
    border:1px solid var(--line); color:var(--text); font-size:13px;
    transition:background .3s, color .3s, border-color .3s, transform .3s;
  }
  .blog-card:hover .blog-go{
    background:var(--accent); border-color:var(--accent); color:#fff; transform:translateX(3px);
  }
  @media (max-width:900px){
    .blog-grid{grid-template-columns:repeat(2,1fr);}
    .blog-grid > *:nth-child(2n){border-right:0;}
    .blog-grid > *:last-child{border-right:0;}
  }
  @media (max-width:620px){
    .blog-grid{grid-template-columns:1fr;}
    .blog-grid > *{border-right:0;}
    .blog-card{min-height:0; padding:24px 20px 22px;}
    .blog-body{margin-top:28px;}
  }

/* ==== YAZI SAYFASI ==== */
  .art-hero{padding:clamp(96px,10vw,150px) 0 clamp(34px,4vw,52px); border-bottom:1px solid var(--line);}
  .art-meta{
    display:flex; align-items:center; gap:12px; margin:26px 0 20px;
    font-family:'JetBrains Mono',monospace; font-size:11px;
    letter-spacing:0.09em; text-transform:uppercase; color:var(--muted);
  }
  .art-meta .art-tag{color:var(--accent);}
