    letter-spacing:-0.025em; line-height:1.2;
    margin:44px 0 16px; padding-top:22px; border-top:1px solid var(--line);
  }
  .art-body h2:first-child{margin-top:0; padding-top:0; border-top:0;}
  .art-next{margin-top:clamp(48px,5vw,72px); border-top:1px solid var(--line); padding-top:8px;}

/* ==== BLOG KARTLARI v2 — GORSEL USTTE, KADEMELI ==== */
  .blog-grid{
    grid-template-columns:repeat(3,1fr); gap:0;
    border-top:1px solid var(--line); align-items:start;
  }
  .blog-grid > *:nth-child(2){margin-top:40px;}
  .blog-grid > *:nth-child(3){margin-top:80px;}

  .blog-card{
    position:relative; display:block; min-height:0;
    padding:0 0 30px; border:0;
    border-right:1px solid var(--line); border-bottom:1px solid var(--line);
    border-radius:0; background:var(--bg); overflow:hidden;
    transition:background .45s ease;
  }
  .blog-grid > *:last-child{border-right:0;}
  .blog-card::before{
    content:""; position:absolute; left:0; top:0; height:2px; width:0;
    background:var(--accent); transition:width .55s cubic-bezier(.2,.7,.3,1); z-index:2;
  }
  .blog-card:hover::before{width:100%;}
  .blog-card:hover{background:var(--bg-alt);}

  .bc-top{
    display:flex; align-items:center; justify-content:space-between; gap:16px;
    padding:16px 22px; border-bottom:1px solid var(--line);
    font-family:'JetBrains Mono',monospace; font-size:10.5px;
    letter-spacing:0.09em; text-transform:uppercase; color:var(--muted);
  }
  .bc-dots{display:flex; gap:4px;}
  .bc-dots i{width:6px; height:6px; display:block; background:var(--line);}
  .bc-dots i.on{background:var(--accent);}

  /* kapak — CSS ile kurulmus soyut kompozisyon */
  .bc-shot{
    position:relative; margin:20px 20px 0; aspect-ratio:4/5;
    overflow:hidden; background:var(--surface);
    transition:transform .7s cubic-bezier(.2,.7,.3,1);
  }
  .blog-card:hover .bc-shot{transform:scale(1.015);}
  .bc-shot::before, .bc-shot::after{content:""; position:absolute; inset:0;}
  .bc-shot-1{background:linear-gradient(150deg,#1c1917 0%,#3a3330 55%,#6f6a5c 100%);}
  .bc-shot-1::before{
    background:radial-gradient(70% 55% at 26% 30%, rgba(255,96,68,.9), transparent 62%);
    mix-blend-mode:screen;
  }
  .bc-shot-1::after{
    background:repeating-linear-gradient(-32deg, rgba(255,255,255,.07) 0 1px, transparent 1px 13px);
  }
  .bc-shot-2{background:linear-gradient(200deg,#ff6044 0%,#e0492f 45%,#171410 100%);}
  .bc-shot-2::before{
    background:radial-gradient(60% 60% at 74% 72%, rgba(255,255,255,.75), transparent 60%);
    mix-blend-mode:overlay;
  }
  .bc-shot-2::after{
    background:conic-gradient(from 210deg at 40% 40%, transparent 0deg, rgba(0,0,0,.35) 120deg, transparent 240deg);
  }
  .bc-shot-3{background:linear-gradient(160deg,#f4f4f2 0%,#d6d2c8 60%,#8d887a 100%);}
  .bc-shot-3::before{
    background:
      linear-gradient(90deg, rgba(23,20,15,.16) 1px, transparent 1px) 0 0/26px 26px,
      linear-gradient(rgba(23,20,15,.16) 1px, transparent 1px) 0 0/26px 26px;
    -webkit-mask-image:radial-gradient(80% 70% at 50% 45%, #000 20%, transparent 78%);
            mask-image:radial-gradient(80% 70% at 50% 45%, #000 20%, transparent 78%);
  }
  .bc-shot-3::after{
    background:linear-gradient(115deg, transparent 46%, rgba(255,96,68,.85) 46% 50%, transparent 50%);
  }

  .bc-body{padding:24px 22px 0;}
  .bc-tag{
    display:flex; align-items:center; gap:8px; margin-bottom:16px;
    font-family:'JetBrains Mono',monospace; font-size:10.5px;
    letter-spacing:0.1em; text-transform:uppercase; color:var(--muted);
  }
  .bc-tag i{width:6px; height:6px; background:var(--accent); display:block;}
  .bc-body h4{
    font-size:clamp(18px,1.7vw,22px); font-weight:500; margin:0;
    letter-spacing:-0.02em; line-height:1.3;
  }
  .bc-body p{color:var(--muted); font-size:14px; line-height:1.6; margin-top:12px;}
  .bc-more{
    display:inline-flex; align-items:center; gap:10px; margin-top:22px;
    font-family:'JetBrains Mono',monospace; font-size:10.5px;
    letter-spacing:0.1em; text-transform:uppercase; color:var(--text);
  }
  .bc-more b{
    width:26px; height:26px; border-radius:50%; display:grid; place-items:center;
    border:1px solid var(--line); font-weight:400; font-size:13px;
    transition:background .3s, color .3s, border-color .3s, transform .3s;
  }
  .blog-card:hover .bc-more b{
    background:var(--accent); border-color:var(--accent); color:#fff; transform:translateX(3px);
  }

  @media (max-width:900px){
    .blog-grid{grid-template-columns:repeat(2,1fr);}
    .blog-grid > *{margin-top:0;}
    .blog-grid > *:nth-child(2n){margin-top:36px; border-right:0;}
    .blog-grid > *:nth-child(2n+1){border-right:1px solid var(--line);}
  }
  @media (max-width:620px){
    .blog-grid{grid-template-columns:1fr;}
    .blog-grid > *{margin-top:0 !important; border-right:0 !important;}
    .bc-shot{aspect-ratio:16/10;}
  }
